            return;
        index = rand() % 5;
        CommentCount = 6;
    }
    long conversation = Game->AddNewConversation(Me, false, false);
    Game->AddPersonToConversation(conversation, Game->GetHero());
    switch (index) {
    case 0:
        Game->AddLineToConversation(conversation, "TEXT_QST_042_LOSTTRADER_QUICK", false, Me, Game->GetHero());
        break;
    case 1:
        Game->AddLineToConversation(conversation, "TEXT_QST_042_LOSTTRADER_FOLLOW", false, Me, Game->GetHero());
        break;
    case 2:
        Game->AddLineToConversation(conversation, "TEXT_QST_042_LOSTTRADER_SCARY", false, Me, Game->GetHero());
        break;
    case 3:
        Game->AddLineToConversation(conversation, "TEXT_QST_042_LOSTTRADER_STUPID", false, Me, Game->GetHero());
        break;
    case 4:
        Game->AddLineToConversation(conversation, "TEXT_QST_042_LOSTTRADER_BROTHER", false, Me, Game->GetHero());
        break;
    default:
        Game->AddLineToConversation(conversation, "TEXT_QST_042_LOSTTRADER_BANTER", false, Me, Game->GetHero());
        break;
    }
}


// ---- harness ----
static const char* const kLines[6] = {
    "TEXT_QST_042_LOSTTRADER_QUICK", "TEXT_QST_042_LOSTTRADER_FOLLOW", "TEXT_QST_042_LOSTTRADER_SCARY",
    "TEXT_QST_042_LOSTTRADER_STUPID", "TEXT_QST_042_LOSTTRADER_BROTHER", "TEXT_QST_042_LOSTTRADER_BANTER" };
static int g_fail;
static bool g_terminating;
static long g_nextConv = 100, g_strings;
static int g_newConvs, g_persons, g_lines;
static char g_lastLine[64];
static CLostTraderTrader* g_trader;
static CScriptThing* g_hero;

CCharString::CCharString(const char* text, long) { PStringData = (void*)text; ++g_strings; }
CCharString::~CCharString() { --g_strings; }
CBase::CBase() {}
CBase::~CBase() {}
CScriptThing::CScriptThing(const CScriptThing& other) : PImp() { (void)other; }
bool CEntityScriptBase::IsActiveThreadTerminating() const { return g_terminating; }
const CScriptThing& CGameScriptInterface::GetHero() const { return *g_hero; }
long CGameScriptInterface::AddNewConversation(const CScriptThing&, bool, bool) const { return 0; }
void CGameScriptInterface::AddPersonToConversation(long, const CScriptThing&) const {}
void CGameScriptInterface::AddLineToConversation(long, const CCharString&, bool, const CScriptThing&, const CScriptThing&) const {}

struct CTestGame : CGameScriptInterface {
    long AddNewConversation(const CScriptThing& speaker, bool a, bool b) const
    {
        if (&speaker != &g_trader->Me || a || b) { printf("FAIL AddNewConversation args\n"); g_fail = 1; }
        ++g_newConvs; return ++g_nextConv;
    }
    void AddPersonToConversation(long conversation, const CScriptThing& person) const
    {
        if (conversation != g_nextConv || &person != g_hero) { printf("FAIL AddPersonToConversation args\n"); g_fail = 1; }
        ++g_persons;
    }
    void AddLineToConversation(long conversation, const CCharString& text, bool a, const CScriptThing& speaker, const CScriptThing& listener) const
    {
        if (conversation != g_nextConv || a || &speaker != &g_trader->Me || &listener != g_hero) { printf("FAIL AddLineToConversation args\n"); g_fail = 1; }
        strcpy(g_lastLine, (const char*)text.PStringData);
        ++g_lines;
    }
};

static void call(int k, int wantLine, unsigned long wantCount)
{
    int lines = g_lines;
    g_lastLine[0] = 0;
    g_trader->MakeRandomComment();
    if (g_lines != lines + 1 || strcmp(g_lastLine, kLines[wantLine]) != 0 || g_trader->CommentCount != wantCount) {
        printf("FAIL call %d: line [%s] want [%s], count %lu want %lu\n", k, g_lastLine, kLines[wantLine], g_trader->CommentCount, wantCount);
        g_fail = 1;
    }
}

int main()
{
    CTestGame game;
    CScriptThing hero;
    CLostTraderTrader trader;
    int k;
    int want[20];
    g_hero = &hero; g_trader = &trader;
    trader.Game = &game;
    trader.CommentCount = 0;

    for (k = 0; k < 6; ++k)
        call(k, k, (unsigned long)k + 1);
    srand(1234);
    for (k = 0; k < 20; ++k)
        want[k] = rand() % 5;
    srand(1234);
    for (k = 0; k < 20; ++k)
        call(6 + k, want[k], 6);
    if (g_newConvs != 26 || g_persons != 26) { printf("FAIL conversation counts\n"); g_fail = 1; }

    g_terminating = true;
    k = g_lines;
    trader.MakeRandomComment();
    if (g_lines != k || g_newConvs != 26 || trader.CommentCount != 7) { printf("FAIL terminating comment\n"); g_fail = 1; }
    trader.CommentCount = 2;                      // the first six do not consult the thread state
    trader.MakeRandomComment();
    if (strcmp(g_lastLine, kLines[2]) != 0 || trader.CommentCount != 3) { printf("FAIL early comment while terminating\n"); g_fail = 1; }
    if (g_strings != 0) { printf("FAIL %ld CCharString leaked\n", g_strings); g_fail = 1; }
    if (g_fail) return 1;
    printf("00ea4de0_TEST PASS\n");
    return 0;
}
